  const pX = (parent.x / 100) * w;
  const pY = (parent.y / 100) * h;
  const sX = (sat.x / 100) * w;
  const sY = (sat.y / 100) * h;

  ctx.beginPath();
  ctx.moveTo(pX, pY);
  ctx.lineTo(sX, sY);
  ctx.strokeStyle = "rgba(187, 215, 0, 0.25)";
