    30→async function findCandidates(dir, minBytes) {
    31→  const candidates = [];
    32→  const entries = await readdir(dir, { withFileTypes: true });
    33→  for (const entry of entries) {
    34→    if (entry.isDirectory()) {
    35→      // Sub-dirs auch durchsuchen (z.B. public/images/magazin/)
    36→      const sub = await findCandidates(join(dir, entry.name), minBytes);
    37→      candidates.push(...sub);
    38→      continue;
    39→    }
    40→    if (!entry.isFile()) continue;
    41→    const ext = extname(entry.name).toLowerCase();
    42→    if (!['.jpg', '.jpeg', '.png'].includes(ext)) continue;
    43→    const fullPath = join(dir, entry.name);
    44→    const s = await stat(fullPath);
    45→    if (s.size < minBytes) continue;
    46→    const webpName = basename(entry.name, ext) + '.webp';
    47→    const webpPath = join(dir, webpName);
    48→    if (existsSync(webpPath)) {
    49→      const ws = await stat(webpPath);
    50→      // Skip if WebP already exists and is non-trivial
    51→      if (ws.size > 1024) continue;
    52→    }
    53→    candidates.push({ src: fullPath, dst: webpPath, size: s.size });
