const MIN_ELAPSED_MS = 3000;
const MAX_LINKS = 5;
const MAX_LENGTH = {
  name: 100,
  email: 254,
  subject: 200,
  message: 5000,
} as const;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export async function registerRoutes(
  httpServer: Server,
  app: Express
): Promise<Server> {

  app.post("/api/contact", async (req, res) => {
    try {
      const { name, email, subject, message, website, elapsedMs } = req.body ?? {};

      // 1. Honeypot: nur Bots füllen das unsichtbare Feld aus.
      //    Erfolg vorgaukeln, aber KEINE Mail versenden und nichts speichern.
      if (typeof website === "string" && website.trim() !== "") {
        return res.json({ success: true, message: "Nachricht gesendet" });
      }

      // 2. Zeit-Falle: unrealistisch schnell nach dem Laden abgeschickt (Bot-typisch).
      //    Erfolg vorgaukeln, aber KEINE Mail versenden.
      if (
        typeof elapsedMs !== "number" ||
        !Number.isFinite(elapsedMs) ||
        elapsedMs < MIN_ELAPSED_MS
      ) {
        return res.json({ success: true, message: "Nachricht gesendet" });
      }

      // 3. Serverseitige Validierung vor dem Mailversand.
      if (!name || !email || !subject || !message) {
        return res.status(400).json({ error: "Alle Felder sind erforderlich" });
      }
      if (
        typeof name !== "string" ||
        typeof email !== "string" ||
        typeof subject !== "string" ||
        typeof message !== "string"
      ) {
        return res.status(400).json({ error: "Ungültige Eingabe" });
      }
      if (
        name.length > MAX_LENGTH.name ||
        email.length > MAX_LENGTH.email ||
        subject.length > MAX_LENGTH.subject ||
        message.length > MAX_LENGTH.message
      ) {
        return res.status(400).json({ error: "Eingabe zu lang" });
      }
      if (!EMAIL_RE.test(email)) {
        return res.status(400).json({ error: "Ungültige E-Mail-Adresse" });
      }
      const linkCount = (message.match(/https?:\/\/|www\./gi) || []).length;
      if (linkCount > MAX_LINKS) {
        return res.status(400).json({ error: "Zu viele Links in der Nachricht" });
      }

      await sendContactEmail({ name, email, subject, message });

      res.json({ success: true, message: "Nachricht gesendet" });
    } catch (error) {
      console.error("Contact form error:", error);
      res.status(500).json({ error: "Fehler beim Senden der Nachricht" });
    }
  });

  return httpServer;
}

