cd /home/runner/workspace
cat > /tmp/remove_cases.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'fs';
import { globSync } from 'glob';

const files = globSync('src/pages/laborcontainer-*.astro');
const commentRe = /<!--\s*(ANONYMIZED\s+)?MINI-CASES\s*-->/;
let report = [];

for (const f of files) {
  const lines = readFileSync(f, 'utf8').split('\n');
  const start = lines.findIndex(l => commentRe.test(l));
  if (start === -1) { report.push(`${f}: KEIN MARKER`); continue; }
  // sanity: next non-empty line after comment must be a <section
  let end = -1;
  for (let i = start + 1; i < lines.length; i++) {
    if (lines[i].trim() === '</section>') { end = i; break; }
    if (i > start + 1 && /<section/.test(lines[i])) { end = -2; break; } // nested section guard
  }
  if (end < 0) { report.push(`${f}: GRENZE NICHT EINDEUTIG (end=${end})`); continue; }
  // verify the removed block actually contains the Realisierungen h2
  const block = lines.slice(start, end + 1).join('\n');
  if (!/Realisierungen – anonymisiert/.test(block)) { report.push(`${f}: BLOCK OHNE Realisierungen-H2 — ABBRUCH`); continue; }
  let removeStart = start, removeEnd = end;
  // also drop one trailing blank line if present
  if (lines[removeEnd + 1] !== undefined && lines[removeEnd + 1].trim() === '') removeEnd++;
  const removedCount = removeEnd - removeStart + 1;
  lines.splice(removeStart, removedCount);
  writeFileSync(f, lines.join('\n'));
  report.push(`${f}: entfernt Zeilen ${removeStart + 1}–${removeEnd + 1} (${removedCount} Zeilen)`);
}
console.log(report.join('\n'));
EOF
node /tmp/remove_cases.mjs
echo; echo "=== Kontrolle: dürfen keine Treffer mehr sein ==="
